def main():
    parser=argparse.ArgumentParser();parser.add_argument('--out', required=True);args=parser.parse_args()
    target=Path(args.out).resolve()
    if target.exists() or target.is_symlink() or target.name!='execution-summary380-revision2.py':
        raise ValueError('Only a new revision2 file; never overwrite originals or summary.json.')
    if not target.is_relative_to(ROOT.resolve()) or not target.parent.is_dir():
        raise ValueError('New output must stay within the project and have an existing parent.')
    raw=SOURCE.read_bytes();module=(HERE/'historical_schema_compat.py').read_bytes()
    if hashlib.sha256(raw).hexdigest()!=EXPECTED_SOURCE or hashlib.sha256(module).hexdigest()!=EXPECTED_MODULE:
        raise ValueError('Exact original sealer/module bytes required.')
    text=raw.decode('utf-8')
    for patch in PATCHES:
        if text.count(patch['anchor'])!=1:raise ValueError('Unique exact local replacement anchor required.')
        text=text.replace(patch['anchor'],patch['replacement'])
    result=text.encode('utf-8')
    if hashlib.sha256(result).hexdigest()!=EXPECTED_CANDIDATE:raise ValueError('Exact candidate bytes differ.')
    ast.parse(text)
    restored=text
    for patch in reversed(PATCHES):
        if restored.count(patch['replacement'])!=1:raise ValueError('Unique inverse anchor required.')
        restored=restored.replace(patch['replacement'],patch['anchor'])
    if restored!=raw.decode('utf-8') or ast.dump(ast.parse(restored),include_attributes=False)!=ast.dump(ast.parse(raw),include_attributes=False):
        raise ValueError('Exact whole original text/AST restoration required.')
    with target.open('xb') as f:f.write(result)
    print(json.dumps({'new_file':str(target.relative_to(ROOT)).replace('\\','/'),'sha256':EXPECTED_CANDIDATE,'bytes':len(result),'sealer_executed':False,'summary_written':False}))
if __name__=='__main__':main()
